package dapr4s.internal.witglue

import dapr4swit.dapr_wasm_components.interfaces.invocation
import dapr4swit.exports.dapr_wasm_components.interfaces.invocation_callback

/** What the Scala 3 side of the wall (compiled by dapr4s's nightly, which has no WIT codegen) supplies to the 2.13
  * export glue in `witExports`. Plain Scala: no WIT annotations, so a non-WIT-aware compiler can implement it.
  *
  * Compiled by Scala 2.13 + the scala-wasm plugin next to the generated bindings (package `dapr4swit`, generated by
  * wit-bindgen-scala from `wasm/wit`, see wasm/build.sbt).
  */
trait InvocationHandler {
  def onInvoke(request: invocation_callback.InvokeRequest): invocation.HttpResponse
}
